# owner: platform
"""Find the stretches of opening hours nobody covers."""

from hourglass.models import Span
from hourglass.merging import intersect_spans, merge_spans


def format_time(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def check_inside(spans, hours) -> None:
    for span in spans:
        if intersect_spans(span, hours) != span:
            raise ValueError(f"outside hours: {span}")


def gap_spans(merged, hours) -> list:
    points = [hours.start]
    for span in merged:
        points += [span.start, span.end]
    points.append(hours.end)
    pairs = zip(points[::2], points[1::2])
    return [Span(begin, stop)
            for begin, stop in pairs if begin < stop]


def find_gaps(spans, hours) -> list:
    """One label per uncovered stretch."""
    spans = list(spans)
    check_inside(spans, hours)
    found = gap_spans(merge_spans(spans), hours)
    return [gap_label(item) for item in found]


def gap_label(gap: Span) -> str:
    begin = format_time(gap.start)
    stop = format_time(gap.end)
    return f"gap {begin}-{stop} ({gap.minutes} min)"
